import React from 'react';
import './ReasoningVisualizer.css';

const ReasoningVisualizer = ({ thoughts, toolCalls, activeThoughtId }) => {
    if (!thoughts || thoughts.length === 0) {
        return (
            <div className="reasoning-visualizer empty">
                <p>No thoughts yet. Start the agent to see reasoning process.</p>
            </div>
        );
    }

    // Group tool calls by thought ID
    const toolCallsByThought = {};
    toolCalls.forEach(toolCall => {
        if (!toolCallsByThought[toolCall.thought_id]) {
            toolCallsByThought[toolCall.thought_id] = [];
        }
        toolCallsByThought[toolCall.thought_id].push(toolCall);
    });

    return (
        <div className="reasoning-visualizer">
            <h2>Reasoning Process</h2>
            <div className="thought-timeline">
                {thoughts.map((thought, index) => (
                    <div 
                        key={thought.id} 
                        className={`thought-container ${thought.id === activeThoughtId ? 'active' : ''}`}
                    >
                        <div className="thought-number">{index + 1}</div>
                        <div className="thought-content">
                            <h3>Thought</h3>
                            <div className="thought-text">{formatThought(thought.content)}</div>

                            {/* Tool calls related to this thought */}
                            {toolCallsByThought[thought.id] && toolCallsByThought[thought.id].map(toolCall => (
                                <div key={toolCall.id} className="tool-call">
                                    <h4>Tool: {toolCall.tool_name}</h4>
                                    <div className="tool-inputs">
                                        <h5>Inputs:</h5>
                                        <pre>{JSON.stringify(toolCall.inputs, null, 2)}</pre>
                                    </div>

                                    {toolCall.outputs && (
                                        <div className="tool-outputs">
                                            <h5>Results:</h5>
                                            <pre>{JSON.stringify(toolCall.outputs, null, 2)}</pre>
                                        </div>
                                    )}

                                    {toolCall.error && (
                                        <div className="tool-error">
                                            <h5>Error:</h5>
                                            <pre>{toolCall.error}</pre>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

const formatThought = (content) => {
    // Extract thought content from the formatted response
    if (content.includes('## Thought')) {
        const parts = content.split('## Thought');
        if (parts.length > 1) {
            // Extract the thought part until the next section (if any)
            let thoughtText = parts[1].trim();
            if (thoughtText.includes('## Action')) {
                thoughtText = thoughtText.split('## Action')[0].trim();
            }
            return thoughtText;
        }
    }
    return content;
};

export default ReasoningVisualizer;
